import{_ as a,c as i,o as e,a2 as t}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"getOperationRecovery","description":"Locate only this swap\'s stopped, owned portals.","frontmatter":{"editLink":false,"rawMarkdown":"# getOperationRecovery\\n\\nLocate only this swap\'s stopped, owned portals. This never restarts its withdrawal or submits recovery.\\n\\n## Import\\n\\n```ts\\nimport { getOperationRecovery } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await getOperationRecovery({ operationId, config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction getOperationRecovery(parameters: WithConfig<{ operationId: string; accountId?: string; signal?: AbortSignal; }>): Promise<OperationRecoveryPortal[]>\\n```\\n\\n## Returns\\n\\n`Promise<OperationRecoveryPortal[]>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `operationId`\\n\\n- **Type:** `string`\\n- **Required:** yes\\n\\nThe swap operation whose stopped portals are located.\\n\\n```ts\\nconst result = await getOperationRecovery({\\n  operationId, // [!code focus]\\n});\\n```\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nThe account that owns the operation. Defaults to the active account.\\n\\n```ts\\nconst result = await getOperationRecovery({\\n  operationId,\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nAborts the portal lookup.\\n\\n```ts\\nconst result = await getOperationRecovery({\\n  operationId,\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await getOperationRecovery({\\n  operationId,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/views/getOperationRecovery.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/views/getOperationRecovery.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/views/getOperationRecovery.md","rawMarkdownTitle":"getOperationRecovery","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/views/getOperationRecovery.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"views","action":"getOperationRecovery"},"relativePath":"sdk/actions/views/getOperationRecovery.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/views/getOperationRecovery.md"};function r(o,s,l,p,h,c){return e(),i("div",null,[...s[0]||(s[0]=[t("",34)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
